        const item = record(value);
        if (Object.keys(item).length !== DECISION_KEYS.length || !DECISION_KEYS.every(key => hasOwn(item, key))) return invalidImport();
        const { scope, identity, boundName, action, candidateId, candidateRevision } = item;
