        if (typeof boundName !== 'string' || boundName.length > DRAFT_V2_LIMITS.name || !['reuse', 'create-distinct', 'replace'].includes(action as string)) return invalidImport();
        if (action === 'create-distinct' ? candidateId !== null || candidateRevision !== null : !objectId(candidateId) || typeof candidateRevision !== 'string' || !revisionPattern.test(candidateRevision)) return invalidImport();
